"""Save as examples/python_basics.py; run with uv run python examples/python_basics.py."""

type WordCounts = dict[str, int]


def count_words(text: str) -> WordCounts:
    if not text.strip():
        raise ValueError("Text must contain at least one word")
    counts: WordCounts = {}
    for word in text.casefold().split():
        counts[word] = counts.get(word, 0) + 1
    return counts


if __name__ == "__main__":
    result = count_words("Hello uv hello")
    print(result)
    repeated = [word for word, count in result.items() if count > 1]
    print(repeated)
    try:
        count_words("")
    except ValueError as error:
        print(f"Invalid input: {error}")
